import ExpoModulesCore
import Foundation
import CryptoKit

/// Raised to JavaScript with a plain message. Messages never contain keys, plaintext or tokens:
/// the Rust layer reports error kinds only, and the vault reports Keychain status codes.
final class CryptoFailure: GenericException<String>, @unchecked Sendable {
  override var reason: String { param }
}

/// Expo module over the Rust engine (MobileCrypto, generated by uniffi). It mirrors the `CryptoBridge`
/// port of @discordy/core one to one; modules/voics-crypto/src/index.ts adapts it.
/// Everything binary is base64, exactly as the Rust layer takes and returns it.
public class VoicsCryptoModule: Module {
  private let vault = StoreKeyVault()
  private let lock = NSLock()
  private var engine: MobileCrypto?
  private var attachmentFiles: [String: URL] = [:]
  private let attachmentDirectory = FileManager.default.temporaryDirectory.appendingPathComponent("voics-private-attachments", isDirectory: true)

  public func definition() -> ModuleDefinition {
    Name("VoicsCrypto")

    OnCreate {
      try? FileManager.default.removeItem(at: self.attachmentDirectory)
    }

    AsyncFunction("readAttachment") { (uri: String) -> String in
      guard let url = URL(string: uri), url.isFileURL else { throw CryptoFailure("Invalid local attachment") }
      let data = try Data(contentsOf: url, options: .mappedIfSafe)
      guard data.count > 0 && data.count <= 64 * 1024 * 1024 else { throw CryptoFailure("Invalid attachment size") }
      return data.base64EncodedString()
    }

    AsyncFunction("encryptAttachment") { (plainB64: String) -> [String: String] in
      guard let plain = Data(base64Encoded: plainB64), !plain.isEmpty, plain.count <= 64 * 1024 * 1024 else { throw CryptoFailure("Invalid attachment") }
      let key = SymmetricKey(size: .bits256)
      let sealed = try AES.GCM.seal(plain, using: key)
      let keyData = key.withUnsafeBytes { Data($0) }
      return ["ciphertext": (sealed.ciphertext + sealed.tag).base64EncodedString(), "key_b64": keyData.base64EncodedString(), "nonce_b64": Data(sealed.nonce).base64EncodedString(), "sha256_b64": Data(SHA256.hash(data: plain)).base64EncodedString()]
    }

    AsyncFunction("decryptAttachment") { (cipherB64: String, keyB64: String, nonceB64: String, hashB64: String, size: Int) -> String in
      guard size > 0, size <= 64 * 1024 * 1024, let data = Data(base64Encoded: cipherB64), data.count == size + 16,
            let key = Data(base64Encoded: keyB64), key.count == 32, let nonce = Data(base64Encoded: nonceB64), nonce.count == 12,
            let hash = Data(base64Encoded: hashB64), hash.count == 32 else { throw CryptoFailure("Invalid attachment") }
      let sealed = try AES.GCM.SealedBox(nonce: AES.GCM.Nonce(data: nonce), ciphertext: data.dropLast(16), tag: data.suffix(16))
      let plain = try AES.GCM.open(sealed, using: SymmetricKey(data: key))
      guard Data(SHA256.hash(data: plain)) == hash else { throw CryptoFailure("Attachment integrity check failed") }
      return plain.base64EncodedString()
    }

    AsyncFunction("uploadAttachment") { (urlString: String, cipherB64: String) async throws in
      guard let url = URL(string: urlString), ["https", "http"].contains(url.scheme ?? ""), let data = Data(base64Encoded: cipherB64), data.count > 16, data.count <= 64 * 1024 * 1024 + 16 else { throw CryptoFailure("Invalid encrypted upload") }
      var request = URLRequest(url: url)
      request.httpMethod = "PUT"
      request.httpShouldHandleCookies = false
      request.setValue("application/octet-stream", forHTTPHeaderField: "Content-Type")
      let (_, response) = try await URLSession.shared.upload(for: request, from: data)
      guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode) else { throw CryptoFailure("Encrypted upload failed") }
    }

    AsyncFunction("downloadAttachment") { (urlString: String) async throws -> String in
      guard let url = URL(string: urlString), ["https", "http"].contains(url.scheme ?? "") else { throw CryptoFailure("Invalid encrypted download") }
      var request = URLRequest(url: url)
      request.httpShouldHandleCookies = false
      let (data, response) = try await URLSession.shared.data(for: request)
      guard let http = response as? HTTPURLResponse, (200..<300).contains(http.statusCode), data.count <= 64 * 1024 * 1024 + 16 else { throw CryptoFailure("Encrypted download failed") }
      return data.base64EncodedString()
    }

    AsyncFunction("storeAttachment") { (id: String, plainB64: String) -> String in
      guard let plain = Data(base64Encoded: plainB64), !plain.isEmpty, plain.count <= 64 * 1024 * 1024 else { throw CryptoFailure("Invalid attachment") }
      try FileManager.default.createDirectory(at: self.attachmentDirectory, withIntermediateDirectories: true)
      let url = self.attachmentDirectory.appendingPathComponent(UUID().uuidString + ".ogg")
      try plain.write(to: url, options: [.atomic, .completeFileProtection])
      self.lock.lock(); defer { self.lock.unlock() }
      if let old = self.attachmentFiles.updateValue(url, forKey: id) { try? FileManager.default.removeItem(at: old) }
      return url.absoluteString
    }

    AsyncFunction("removeAttachment") { (id: String) in
      self.lock.lock(); defer { self.lock.unlock() }
      if let url = self.attachmentFiles.removeValue(forKey: id) { try? FileManager.default.removeItem(at: url) }
    }

    AsyncFunction("initialise") { (userId: String, deviceLabel: String) -> String in
      let opened = try self.open(userId: userId, deviceLabel: deviceLabel)
      return try self.guarded { try opened.ensureIdentity() }
    }

    AsyncFunction("sign") { (dataB64: String) -> String in
      try self.guarded { try self.current().sign(dataB64: dataB64) }
    }

    AsyncFunction("verify") { (publicKeyB64: String, dataB64: String, signatureB64: String) -> Bool in
      try self.guarded { try verifySignatureB64(publicKeyB64: publicKeyB64, dataB64: dataB64, signatureB64: signatureB64) }
    }

    AsyncFunction("generateKeyPackages") { (count: Int) -> [String] in
      try self.guarded { try self.current().generateKeyPackages(count: UInt32(clamping: max(count, 1))) }
    }

    AsyncFunction("hasGroup") { (groupId: String) -> Bool in
      try self.guarded { try self.current().hasGroup(groupId: groupId) }
    }

    AsyncFunction("deleteGroup") { (groupId: String) -> Bool in
      try self.guarded { try self.current().deleteGroup(groupId: groupId) }
    }

    AsyncFunction("createGroup") { (groupId: String) -> Int in
      try self.guarded { Int(try self.current().createGroup(groupId: groupId)) }
    }

    AsyncFunction("addMembers") { (groupId: String, keyPackagesB64: [String]) -> [String: Any] in
      try self.guarded {
        let out = try self.current().addMembers(groupId: groupId, keyPackagesB64: keyPackagesB64)
        return ["commitB64": out.commitB64, "welcomeB64": out.welcomeB64, "epoch": Int(out.epoch)]
      }
    }

    AsyncFunction("memberKeys") { (groupId: String) -> [String] in
      try self.guarded { try self.current().memberKeys(groupId: groupId) }
    }

    AsyncFunction("removeMembers") { (groupId: String, identityKeysB64: [String]) -> [String: Any]? in
      try self.guarded {
        guard let out = try self.current().removeMembers(groupId: groupId, identityKeysB64: identityKeysB64) else { return nil }
        return ["commitB64": out.commitB64, "epoch": Int(out.epoch)]
      }
    }

    AsyncFunction("joinFromWelcome") { (welcomeB64: String) -> [String: Any] in
      try self.guarded {
        let out = try self.current().joinFromWelcome(welcomeB64: welcomeB64)
        return ["groupId": out.groupId, "epoch": Int(out.epoch)]
      }
    }

    AsyncFunction("encrypt") { (groupId: String, plaintextB64: String) -> [String: Any] in
      try self.guarded {
        let out = try self.current().encrypt(groupId: groupId, plaintextB64: plaintextB64)
        return ["ciphertextB64": out.ciphertextB64, "epoch": Int(out.epoch)]
      }
    }

    AsyncFunction("processIncoming") { (groupId: String, messageB64: String) -> [String: Any] in
      try self.guarded {
        let out = try self.current().processIncoming(groupId: groupId, messageB64: messageB64)
        var result: [String: Any] = ["kind": out.kind]
        if let plaintext = out.plaintextB64 { result["plaintextB64"] = plaintext }
        if let sender = out.senderIdentity { result["senderIdentity"] = sender }
        if let epoch = out.epoch { result["epoch"] = Int(epoch) }
        return result
      }
    }

    AsyncFunction("exportSecret") { (groupId: String, label: String, length: Int) -> String in
      try self.guarded { try self.current().exportSecret(groupId: groupId, label: label, length: UInt32(clamping: max(length, 0))) }
    }

    AsyncFunction("putMessage") { (channelId: String, messageId: String, sortKey: Int, json: String) in
      try self.guarded {
        try self.current().putMessage(record: StoredRecord(channelId: channelId, messageId: messageId, sortKey: Int64(sortKey), json: json))
      }
    }

    AsyncFunction("listMessages") { (channelId: String, beforeSortKey: Int?, limit: Int) -> [[String: Any]] in
      try self.guarded {
        let rows = try self.current().listMessages(
          channelId: channelId,
          beforeSortKey: beforeSortKey.map { Int64($0) },
          limit: UInt32(clamping: max(limit, 0)))
        return rows.map { ["channelId": $0.channelId, "messageId": $0.messageId, "sortKey": Int($0.sortKey), "json": $0.json] }
      }
    }

    AsyncFunction("deleteMessage") { (channelId: String, messageId: String) in
      try self.guarded { try self.current().deleteMessage(channelId: channelId, messageId: messageId) }
    }
  }

  /// Opens (or reopens) the encrypted store of one user; the key comes from the Keychain.
  private func open(userId: String, deviceLabel: String) throws -> MobileCrypto {
    guard userId.range(of: "^[0-9]{1,20}$", options: .regularExpression) != nil else { throw CryptoFailure("invalid user id") }
    return try guarded {
      let path = try self.databasePath(userId: userId)
      let opened = try MobileCrypto.open(path: path, keyHex: try self.vault.hexKey(for: userId), credentialLabel: "\(userId):\(deviceLabel)")
      self.lock.lock()
      self.engine = opened
      self.lock.unlock()
      return opened
    }
  }

  private func current() throws -> MobileCrypto {
    lock.lock()
    defer { lock.unlock() }
    guard let engine else { throw CryptoFailure("crypto store not initialised; sign in first") }
    return engine
  }

  /// Application Support/voics/crypto/<user>.db: private to the app, kept out of iCloud and device backups, and
  /// readable after the first unlock so messages can arrive while the phone is locked.
  private func databasePath(userId: String) throws -> String {
    let files = FileManager.default
    var folder = try files.url(for: .applicationSupportDirectory, in: .userDomainMask, appropriateFor: nil, create: true)
      .appendingPathComponent("voics", isDirectory: true)
      .appendingPathComponent("crypto", isDirectory: true)
    try files.createDirectory(
      at: folder, withIntermediateDirectories: true,
      attributes: [.protectionKey: FileProtectionType.completeUntilFirstUserAuthentication])
    var values = URLResourceValues()
    values.isExcludedFromBackup = true
    try folder.setResourceValues(values)
    return folder.appendingPathComponent("\(userId).db").path
  }

  /// Runs `body`, turning any failure into a plain CryptoFailure (the description carries no secret material).
  private func guarded<T>(_ body: () throws -> T) throws -> T {
    do {
      return try body()
    } catch let failure as CryptoFailure {
      throw failure
    } catch {
      throw CryptoFailure(String(describing: error))
    }
  }
}
